{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Compound 74, a sulfonamide/amide/tertiary-amine/pyridine analogue, showed no measurable CNS penetration (B/P and Kp,uu both 0) with an efflux ratio of 60, directly demonstrating that this chemotype can be an efflux-limited non-penetrant despite moderate lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In rats, the phenethylamide MBDA had only 0.06% injected dose/g brain uptake and was classified as poor penetration; the query shares the arylethyl-amide motif and multiple polar ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sulfasalazine, containing a sulfonamide, pyridine, and carboxylic acid, had brain concentrations below the LLOQ in mice, showing that combining these polar groups can essentially abolish brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "HBED, the closest-scoring analogue, was measured at ~10 µM in forebrain tissue and classified permeable, providing some evidence that polyacidic/tertiary-amine chelator-like structures can reach brain; however, it lacks the sulfonamide and amide and is structurally distinct from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Pritelivir, a lipophilic sulfonamide/pyridine drug, penetrated the BBB in mice, showing that sulfonamide/pyridine alone does not preclude CNS access; the query's additional carboxylic acid and basic tertiary amine are the differentiating liabilities.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query combines a primary sulfonamide, amide, tertiary amine, carboxylic acid, and pyridine, yielding a zwitterionic, high-TPSA molecule. Direct evidence from the closest functional analogue (C10) shows complete lack of CNS penetration with strong efflux, and additional polar sulfonamide/acid analogues (C04, C01) are poor. Permeable sulfonamide/pyridine comparators (C06, C07) are less transferable because they lack the query's ionizable acid/amine combination. Overall, inadequate CNS access is predicted.",
  "evidence_gaps": [
    "No direct PK or brain concentration data for the query itself",
    "Unknown whether the query is a P-gp/BCRP substrate in vivo",
    "Conflicting evidence from HBED and pritelivir suggests some structurally related polar sulfonamides can access brain under certain conditions"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

